CREATE TABLE IF NOT EXISTS financial_budgets (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',subject_component TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,title TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'SAR' CHECK(length(currency)=3),budget_limit_minor INTEGER NOT NULL CHECK(budget_limit_minor>=0),owner_type TEXT NOT NULL DEFAULT 'user',owner_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','closed','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS financial_entries (id INTEGER PRIMARY KEY AUTOINCREMENT,budget_id INTEGER NOT NULL,entry_type TEXT NOT NULL CHECK(entry_type IN ('estimate','commitment','expense','credit')),category TEXT NOT NULL,description TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>=0),supplier_reference TEXT,document_component TEXT,document_id TEXT,occurred_at TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(budget_id) REFERENCES financial_budgets(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS expenditure_requests (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',budget_id INTEGER,subject_component TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,request_type TEXT NOT NULL CHECK(request_type IN ('petty_cash','procurement','reimbursement','other')),title TEXT NOT NULL,purpose TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL DEFAULT 'SAR' CHECK(length(currency)=3),requester_type TEXT NOT NULL DEFAULT 'user',requester_id TEXT NOT NULL,approval_component TEXT,approval_id TEXT,evidence_component TEXT,evidence_id TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','rejected','paid','reconciled','withdrawn')),reconciliation_notes TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(budget_id) REFERENCES financial_budgets(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_financial_budget_subject ON financial_budgets(app_id,subject_component,subject_type,subject_id,status);CREATE INDEX IF NOT EXISTS idx_financial_entries ON financial_entries(budget_id,entry_type,status);CREATE INDEX IF NOT EXISTS idx_expenditure_subject ON expenditure_requests(app_id,subject_component,subject_type,subject_id,status);
